        /// An action literal as the AgentAction the app runs.
        public static AgentAction Action(string json)
        {
            var o = JObject.Parse(json);
            return new AgentAction { name = (string)o["name"], args = o["args"] as JObject ?? new JObject() };
        }

        public static JObject Args(string json) => Action(json).args;
        public static JObject Body(string json) => JObject.Parse(json);

        /// Every action example, in the order GrokCheck("g3") runs them (the rules pair and flythrough → video as the
        /// backend sends them: in one reply).
        public static IEnumerable<(string id, string[] actions)> Replies()
        {
            yield return ("show_postcard", new[] { Postcard });
            yield return ("show_safety", new[] { SafetyRecalled });
            yield return ("show_reimagined", new[] { ReimaginedKitchen });
            yield return ("flythrough_started", new[] { FlythroughStarted });
            yield return ("show_video", new[] { Video });
            yield return ("show_manual_answer", new[] { Manual });
            yield return ("show_packet", new[] { PacketPublic });
            yield return ("packet_revoked", new[] { PacketRevoked });
            yield return ("show_report", new[] { Report });
            yield return ("show_share_preview", new[] { Share });
            yield return ("show_installers", new[] { Installers });
            yield return ("rules", new[] { RulesStarted, RulesDone });
            yield return ("show_quote_check", new[] { QuoteBad });
        }
    }
